    public Settings members(RefCounted document,string root)
    {
        if(document.Call("track_for_id",root).AsGodotDictionary().Count==0)return Failure("Choose an existing track or group.");var tracks=new GArray();var ids=new System.Collections.Generic.HashSet<string>();using var renderer=new AudioRendererOperations();using var lanes=new AudioAutomationLaneOperations();foreach(var raw in document.Get("tracks").AsGodotArray()){var track=raw.AsGodotDictionary();if(S(track,"id")!=root&&!renderer.route_reaches(document,S(track,"id"),root,new Settings()))continue;if(B(track,"locked")||track.ContainsKey("frozen_track")||track.ContainsKey("frozen_source"))return Failure("Unlock/unfreeze every incoming track before freezing this routed group.");if(lanes.is_lane(track))continue;tracks.Add(track);ids.Add(S(track,"id"));}foreach(var raw in tracks){var track=raw.AsGodotDictionary();if(S(track,"id")==root)continue;if(!ids.Contains(S(track,"output")))return Failure("An incoming track also has a dry output outside this group. Route it entirely inside the group, or bounce without replacing the sources.");foreach(var send in Get(track,"sends",new GArray()).AsGodotArray())if(!ids.Contains(S(send.AsGodotDictionary(),"target")))return Failure("An incoming track sends audio outside the group. Freeze would lose that branch; use Bounce or reroute it first.");}return new Settings{["error"]="",["tracks"]=tracks};
    }
    public string apply(RefCounted session,string root,AudioStream stream)
    {
        var document=session.Get("document").As<RefCounted>();var prepared=members(document,root);if(S(prepared,"error").Length>0)return S(prepared,"error");if(stream==null||stream.GetLength()<=0)return "No frozen audio is available.";var original=document.Call("track_for_id",root).AsGodotDictionary();var state=new GArray();bool anySolo=false;foreach(var raw in prepared["tracks"].AsGodotArray()){var track=raw.AsGodotDictionary();state.Add(new Settings{["id"]=S(track,"id"),["mute"]=B(track,"mute"),["solo"]=B(track,"solo"),["locked"]=B(track,"locked")});anySolo|=B(track,"solo");}session.Call("action","Freeze routed track/group",Callable.From(()=>{using var documents=new AudioDocumentOperations();var frozen=documents.add_track(document,"Frozen "+S(original,"name","Track"),"audio");frozen["output"]=Get(original,"output","");frozen["sends"]=Get(original,"sends",new GArray()).AsGodotArray().Duplicate(true);frozen["frozen_source"]=root;frozen["locked"]=true;frozen["mute"]=B(original,"mute");frozen["solo"]=anySolo;var clip=documents.insert_source(document,stream,S(frozen,"id"),0,"Frozen routed audio");if(clip!=null){var values=document.Call("actor_for_clip",clip.Get("id")).AsGodotObject().Get("values").AsGodotDictionary();values[new StringName("fade_in")]=0.0;values[new StringName("fade_out")]=0.0;}original["freeze_members"]=state;original["frozen_track"]=S(frozen,"id");foreach(var raw in prepared["tracks"].AsGodotArray()){var track=raw.AsGodotDictionary();track["mute"]=true;track["solo"]=false;track["locked"]=true;}}));return "";
    }
    public void restore_members(RefCounted document,Settings original){foreach(var raw in Get(original,"freeze_members",new GArray()).AsGodotArray()){var state=raw.AsGodotDictionary();var track=document.Call("track_for_id",S(state,"id")).AsGodotDictionary();if(track.Count==0)continue;foreach(string key in new[]{"mute","solo","locked"})track[key]=state[key];}original.Remove("freeze_members");}
}
public partial class AudioConductorFitOperations:RefCounted
{
    private static Variant Get(Settings d,string key,Variant fallback=default)=>d.TryGetValue(key,out var v)?v:fallback;
