    private static Settings Failure(string error)=>new(){["error"]=error};
    public Settings prepare(RefCounted session,GArray ids)
    {
        if(ids.Count==0||session.Get("_before").AsGodotObject()!=null)return Failure("Select full note clips and finish the current adjustment.");var document=session.Get("document").AsGodotObject();using var conductor=document.Call("conductor").As<RefCounted>();var operations=new GArray();string error=conductor.Get("error").AsString();if(error.Length>0)return Failure(error);using var edits=new AudioEditSessionOperations();using var conductorOps=new AudioConductorOperations();using var timingOps=new AudioTempoMapOperations();foreach(var id in ids){var clip=document.Call("clip_for_id",id.AsString()).AsGodotObject();var actor=document.Call("actor_for_clip",id.AsString()).AsGodotObject();if(clip==null||actor==null||!edits.can_edit(session,id.AsString())||!edits.is_note_source(actor))return Failure("Every selected clip must be an unlocked editable note source.");var values=actor.Get("values").AsGodotDictionary();double length=N(values,"source_duration"),beats=N(values,"pattern_beats");if(clip.Get("source_offset").AsDouble()>.00001||!Mathf.IsEqualApprox(clip.Get("playback_speed").AsDouble(),1)||Get(values,"loop",false).AsBool()||Get(values,"reverse",false).AsBool()||Math.Abs(clip.Get("duration").AsDouble()-length)>.01)return Failure("Conductor fitting requires full, forward, unlooped note clips at normal speed. Keep trimmed/stretched sources unchanged or duplicate a full source first.");if(beats<=0)return Failure("A source has no explicit pattern length.");double origin=conductorOps.seconds_to_beat(conductor,clip.Get("start_time").AsDouble()),bpm=conductorOps.tempo_at(conductor,clip.Get("start_time").AsDouble());var tempos=new GArray{new Settings{["beat"]=0.0,["bpm"]=bpm}};foreach(var raw in document.Get("tempo_points").AsGodotArray()){var point=raw.AsGodotDictionary();double local=N(point,"beat")-origin;if(local>.000001&&local<beats)tempos.Add(new Settings{["beat"]=local,["bpm"]=point["bpm"]});}using var timing=KiwiAudioTempoMap.create(tempos,bpm,1.0);double duration=timingOps.beat_to_seconds(timing,beats);if(timing.Get("error").AsString().Length>0||duration>300)return Failure("The fitted source would exceed the five-minute editable-note limit.");operations.Add(new Settings{["clip"]=clip,["actor"]=actor,["tempos"]=tempos,["bpm"]=bpm,["duration"]=duration});}return new Settings{["error"]="",["operations"]=operations};
    }
    public string apply(RefCounted session,GArray ids){var prepared=prepare(session,ids);string error=Get(prepared,"error","").AsString();if(error.Length>0)return error;session.Call("action","Fit notes to conductor snapshot",Callable.From(()=>{foreach(var raw in prepared["operations"].AsGodotArray()){var operation=raw.AsGodotDictionary();var values=operation["actor"].AsGodotObject().Get("values").AsGodotDictionary();values[new StringName("source_bpm")]=operation["bpm"];values[new StringName("midi_tempos")]=operation["tempos"];values[new StringName("midi_tempo_scale")]=1.0;values[new StringName("notes_dirty")]=true;values.Remove(new StringName("notes_source_scale"));operation["clip"].AsGodotObject().Set("duration",operation["duration"]);}}));return "";}
}
public partial class AudioModulationMatrixOperations:RefCounted
{
    private static Variant Get(Settings d,string key,Variant fallback=default)=>d.TryGetValue(key,out var v)?v:fallback;
    public string apply(RefCounted session,GArray rows)
