        if(session.Get("_before").AsGodotObject()!=null||rows.Count==0||rows.Count>32)return "Finish the current adjustment; a matrix supports 1–32 targets.";var operations=new GArray();var seen=new System.Collections.Generic.HashSet<string>();var document=session.Get("document").AsGodotObject();using var lanes=new AudioAutomationLaneOperations();using var modulation=new AudioAutomationCanvasOperations();foreach(var raw in rows){var row=raw.AsGodotDictionary();var target=Get(row,"target",new Settings()).AsGodotDictionary();var info=lanes.resolve(document,target);string key=lanes.key(target);if(info.Count==0||info["locked"].AsBool()||!seen.Add(key))return "Every modulation target must be available, unlocked and unique.";double seconds=Math.Min(600,info["duration"].AsDouble());if(info["duration"].AsDouble()>600)return "Split sources or select a shorter composition before generating modulation (10-minute curve limit).";var values=modulation.modulation_points(row,seconds,document.Get("tempo").AsDouble(),info["minimum"].AsDouble(),info["maximum"].AsDouble());operations.Add(new Settings{["info"]=info,["values"]=values});}session.Call("action","Apply modulation matrix",Callable.From(()=>{foreach(var raw in operations){var operation=raw.AsGodotDictionary();var info=operation["info"].AsGodotDictionary();var owner=info["owner"].AsGodotDictionary();var curves=Get(owner,"automation",new Settings()).AsGodotDictionary().Duplicate(true);curves[info["parameter"].AsString()]=operation["values"];owner["automation"]=curves;}document.Get("presets").AsGodotDictionary()["modulation_matrix"]=rows.Duplicate(true);}));return "";
